import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import {
  Activity, AlertTriangle, CheckCircle2, Clock3, Database, FileClock, Filter,
  KeyRound, LockKeyhole, Mail, Network, PauseCircle, PlayCircle, Plug, Plus,
  RefreshCw, Search, Server, ShieldCheck, Trash2, Webhook, Workflow, X, Download, LayoutGrid, List
} from 'lucide-react';
import { api } from './api';
import { downloadCsv } from './list-workbench';
import './admin-system-workspaces.css';

const date = (value?: string) => value ? new Date(value).toLocaleString('pt-BR') : '—';
const slug = (value: string) => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const labels: Record<string, string> = {
  queued: 'Na fila', processing: 'Processando', completed: 'Concluído', failed: 'Falhou', connected: 'Conectado',
  ready: 'Pronto', error: 'Com erro', draft: 'Rascunho', disabled: 'Desativado', accepted: 'Recebido',
  sent: 'Enviado', active: 'Ativo', pending: 'Pendente', resolved: 'Resolvido', archived: 'Arquivado', paused: 'Pausado', open: 'Aberto', investigating: 'Investigando', contained: 'Contido', false_positive: 'Falso positivo',
  low: 'Baixa', medium: 'Média', high: 'Alta', critical: 'Crítica'
};
type ModuleRecord = { id: string; title: string; companyName?: string; tenantId?: string; status: string; priority: string; owner?: string; dueAt?: string; payload?: Record<string, unknown>; updatedAt?: string };
type RegistryDefinition = { title: string; text: string; action: string; first: string; second: string };
const registryDefinitions: Record<string, RegistryDefinition> = {
  'integrations:APIs': { title: 'Contratos e consumidores de API', text: 'Documente integrações, escopos, limites e responsáveis além das chaves emitidas pelas empresas.', action: 'Registrar contrato', first: 'Endpoint / aplicação', second: 'Escopos e limite' },
  'integrations:Webhooks': { title: 'Destinos e assinaturas', text: 'Governança dos destinos, segredos, eventos e política de repetição.', action: 'Cadastrar destino', first: 'URL de destino', second: 'Eventos assinados' },
  'integrations:ERP': { title: 'Implantações e mapeamentos ERP', text: 'Acompanhe homologação, mapeamentos e responsáveis por cada conector.', action: 'Planejar implantação', first: 'Provedor / ambiente', second: 'Entidades sincronizadas' },
  'integrations:CRM': { title: 'Conectores CRM', text: 'Pipelines, direção de sincronização, consentimento e propriedade dos dados.', action: 'Cadastrar CRM', first: 'Provedor / pipeline', second: 'Direção e frequência' },
  'integrations:Pagamentos': { title: 'Gateways de pagamento', text: 'Credenciamento, ambiente, métodos habilitados e conciliação financeira.', action: 'Cadastrar gateway', first: 'Provedor / ambiente', second: 'Métodos e conta recebedora' },
  'integrations:E-mail': { title: 'Provedores e remetentes', text: 'Domínios verificados, reputação, remetentes e templates transacionais.', action: 'Cadastrar remetente', first: 'Provedor / domínio', second: 'Remetente e limite diário' },
  'integrations:SSO': { title: 'Provedores de identidade', text: 'Configurações SAML/OIDC, domínios e política de provisionamento.', action: 'Cadastrar SSO', first: 'Protocolo / issuer', second: 'Domínios e provisionamento' },
  'operations:Filas': { title: 'Políticas das filas', text: 'Defina prioridade, concorrência, retenção e tratamento de mensagens mortas.', action: 'Criar política de fila', first: 'Fila / concorrência', second: 'Retenção e dead letter' },
  'operations:Exportações': { title: 'Solicitações de exportação', text: 'Controle datasets, filtros, destinatários e expiração dos arquivos.', action: 'Nova exportação', first: 'Dataset / formato', second: 'Filtros e destinatário' },
  'operations:Agendamentos': { title: 'Rotinas recorrentes', text: 'Programe execução, fuso, responsável e política de falha.', action: 'Novo agendamento', first: 'Rotina / frequência', second: 'Horário, fuso e falha' },
  'monitoring:APIs': { title: 'Monitores sintéticos', text: 'Endpoints críticos, intervalos, timeout e metas de disponibilidade.', action: 'Criar monitor', first: 'Endpoint / método', second: 'Intervalo, timeout e SLA' },
  'monitoring:Logs': { title: 'Consultas e alertas salvos', text: 'Pesquisas operacionais, retenção, severidade e notificação.', action: 'Salvar consulta', first: 'Consulta / fonte', second: 'Retenção e alerta' },
  'security:LGPD': { title: 'Solicitações de titulares', text: 'Registre acesso, correção, portabilidade e exclusão com prazo e evidências.', action: 'Abrir processo LGPD', first: 'Titular / solicitação', second: 'Base legal e prazo' }
};

export const isSystemWorkspace = (page: string, subpage: string) => ['integrations', 'operations', 'security'].includes(page) || (page === 'monitoring' && subpage !== 'Incidentes') || (page === 'support' && subpage !== 'Chamados');

export function AdminSystemWorkspace({ page, subpage }: { page: string; subpage: string }) {
  const [data, setData] = useState<any>();
  const [records, setRecords] = useState<ModuleRecord[]>([]);
  const [query, setQuery] = useState('');
  const [status, setStatus] = useState('all');
  const [company, setCompany] = useState('all');
  const [period, setPeriod] = useState('30');
  const [notice, setNotice] = useState('');
  const section = slug(subpage);
  const load = async () => {
    const [system, registry] = await Promise.all([api('/platform/system'), api(`/platform/modules/${page}/${section}`).catch(() => ({ records: [] }))]);
    setData(system); setRecords((registry as { records?: ModuleRecord[] }).records || []);
  };
  useEffect(() => { setQuery(''); setStatus('all'); setCompany('all'); setPeriod('30'); void load(); }, [page, section]);
  const filtered = useMemo(() => {
    if (!data) return data;
    const apply = (rows: any[]) => rows.filter(row => {
      const timestamp = row.createdAt || row.occurredAt || row.lastSyncAt || row.startedAt || row.updatedAt;
      const insidePeriod = period === 'all' || !timestamp || new Date(timestamp).getTime() >= Date.now() - Number(period) * 86_400_000;
      return insidePeriod && (!query || JSON.stringify(row).toLowerCase().includes(query.toLowerCase())) && (status === 'all' || String(row.status ?? (row.success ? 'success' : 'failed')) === status) && (company === 'all' || row.tenantId === company || row.companyName === company);
    });
    return { ...data, jobs: apply(data.jobs || []), connectors: apply(data.connectors || []), apiKeys: apply(data.apiKeys || []), webhooks: apply(data.webhooks || []), outbound: apply(data.outbound || []), auditLogs: apply(data.auditLogs || []), accessLogs: apply(data.accessLogs || []), loginAttempts: apply(data.loginAttempts || []), sessions: apply(data.sessions || []), securityEvents: apply(data.securityEvents || []) };
  }, [data, query, status, company, period]);
  if (!data) return <div className="pa-notice">Carregando dados gerenciais da plataforma...</div>;
  const common = { data: filtered, raw: data, records, load, notice, setNotice };
  return <section className="pa-system-workspace">
    <ManagerFilters query={query} setQuery={setQuery} status={status} setStatus={setStatus} company={company} setCompany={setCompany} period={period} setPeriod={setPeriod} tenants={data.tenants || []} onRefresh={() => void load()} />
    {notice && <div className="pa-notice">{notice}<button onClick={() => setNotice('')}>×</button></div>}
    {page === 'integrations' && <IntegrationWorkspace subpage={subpage} {...common} />}
    {page === 'operations' && <OperationsWorkspace subpage={subpage} {...common} />}
    {page === 'monitoring' && <MonitoringWorkspace subpage={subpage} {...common} />}
    {page === 'security' && <SecurityWorkspace subpage={subpage} {...common} />}
    {page === 'support' && <SupportWorkspace subpage={subpage} data={data} setNotice={setNotice} />}
  </section>;
}

function ManagerFilters({ query, setQuery, status, setStatus, company, setCompany, period, setPeriod, tenants, onRefresh }: any) {
  return <div className="pa-system-filters"><span><Filter /> Filtros desta visão</span><label><Search /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Pesquisar registros..." /></label><select aria-label="Filtrar por período" value={period} onChange={event => setPeriod(event.target.value)}><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option><option value="365">Últimos 12 meses</option><option value="all">Todo o histórico</option></select><select aria-label="Filtrar por empresa" value={company} onChange={event => setCompany(event.target.value)}><option value="all">Todas as empresas</option>{tenants.map((tenant: any) => <option key={tenant.id} value={tenant.id}>{tenant.name}</option>)}</select><select aria-label="Filtrar por status" value={status} onChange={event => setStatus(event.target.value)}><option value="all">Todos os status</option><option value="connected">Conectado</option><option value="ready">Pronto</option><option value="queued">Na fila</option><option value="processing">Processando</option><option value="completed">Concluído</option><option value="failed">Falhou</option><option value="error">Com erro</option></select><button onClick={onRefresh} title="Atualizar dados"><RefreshCw /></button></div>;
}
function Head({ eyebrow, title, text, icon }: { eyebrow: string; title: string; text: string; icon: ReactNode }) { return <header className="pa-advanced-head"><div><small>{eyebrow}</small><h2>{title}</h2><p>{text}</p></div>{icon}</header>; }
function Metrics({ items }: { items: [string, ReactNode, string?][] }) { return <div className="pa-kpis module">{items.map(([label, value, hint]) => <article className="pa-kpi" key={label}><span>{label}</span><b>{value}</b>{hint && <small>{hint}</small>}</article>)}</div>; }
function Badge({ value }: { value: string | number }) { const text = labels[String(value)] || String(value); return <i className={`pa-state ${String(value)}`}>{text}</i>; }
function Empty({ children = 'Nenhum registro encontrado para os filtros selecionados.' }: { children?: ReactNode }) { return <div className="pa-empty">{children}</div>; }

function IntegrationWorkspace({ subpage, data, records, load, setNotice }: any) {
  if (subpage === 'APIs') {
    const keys = data.apiKeys || [], active = keys.filter((item: any) => item.active).length, used = keys.filter((item: any) => item.lastUsedAt).length;
    return <><Head eyebrow="INTEGRAÇÕES / GOVERNANÇA" title="APIs e credenciais" text="Inventário global de chaves, escopos, utilização e validade por empresa." icon={<Network />} /><Metrics items={[["Chaves emitidas", keys.length], ["Chaves ativas", active], ["Utilizadas", used], ["Sem uso", keys.length - used, 'Revisar credenciais ociosas']]} /><Table heads={['Empresa / chave', 'Prefixo', 'Escopos', 'Último uso', 'Controle']} rows={keys.map((key: any) => [<span><b>{key.companyName}</b><small>{key.name}</small></span>, key.keyPrefix, safeList(key.scopes), date(key.lastUsedAt), <button className="pa-inline-action" onClick={async () => { await api(`/platform/api-keys/${key.id}`, { method: 'PATCH', body: JSON.stringify({ active: !key.active }) }); setNotice(key.active ? 'Chave pausada e auditada.' : 'Chave reativada e auditada.'); await load(); }}>{key.active ? <PauseCircle /> : <PlayCircle />}{key.active ? 'Pausar' : 'Ativar'}</button>])} /><RegistryPanel page="integrations" subpage={subpage} records={records} tenants={data.tenants} onChange={load} /></>;
  }
  if (subpage === 'Webhooks') {
    const items = data.webhooks || [], failed = items.filter((item: any) => ['failed', 'error'].includes(item.status)).length;
    return <><Head eyebrow="INTEGRAÇÕES / EVENTOS" title="Webhooks" text="Entrega de eventos, processamento, tentativas e recuperação de falhas." icon={<Webhook />} /><Metrics items={[["Eventos recebidos", items.length], ["Processados", items.filter((x: any) => x.processedAt).length], ["Com falha", failed], ["Tentativas", items.reduce((sum: number, x: any) => sum + Number(x.attempts || 0), 0)]]} /><Table heads={['Empresa', 'Provedor / evento', 'Recebido', 'Situação', 'Ação']} rows={items.map((item: any) => [item.companyName, <span><b>{item.provider}</b><small>{item.eventType}</small></span>, date(item.occurredAt || item.createdAt), <span><Badge value={item.status} />{item.lastError && <small>{item.lastError}</small>}</span>, ['failed', 'error'].includes(item.status) ? <button className="pa-inline-action" onClick={async () => { await api(`/platform/webhooks/${item.id}/retry`, { method: 'POST' }); setNotice('Webhook reenfileirado para processamento.'); await load(); }}><RefreshCw /> Reprocessar</button> : '—'])} /><RegistryPanel page="integrations" subpage={subpage} records={records} tenants={data.tenants} onChange={load} /></>;
  }
  if (subpage === 'ERP') {
    const connectors = (data.connectors || []).filter((item: any) => item.kind === 'erp');
    return <><Head eyebrow="INTEGRAÇÕES / ERP" title="Conectores ERP" text="Saúde, capacidades, última sincronização e ciclo de homologação dos ERPs." icon={<Plug />} /><Metrics items={[["Conectores", connectors.length], ["Prontos", connectors.filter((x: any) => x.status === 'ready').length], ["Com erro", connectors.filter((x: any) => x.status === 'error' || x.lastError).length], ["Sincronizados", connectors.filter((x: any) => x.lastSyncAt).length]]} /><Table heads={['Empresa / conector', 'Tecnologia', 'Capacidades', 'Última sincronização', 'Controle']} rows={connectors.map((item: any) => [<span><b>{item.companyName}</b><small>{item.name} · {item.provider}</small></span>, item.connectionType, safeList(item.capabilities), <span>{date(item.lastSyncAt)}{item.lastError && <small className="danger-text">{item.lastError}</small>}</span>, <button className="pa-inline-action" onClick={async () => { const next = item.status === 'disabled' ? 'ready' : 'disabled'; await api(`/platform/connectors/${item.id}`, { method: 'PATCH', body: JSON.stringify({ status: next }) }); setNotice(next === 'ready' ? 'Conector liberado para operação.' : 'Conector pausado com rastreabilidade.'); await load(); }}>{item.status === 'disabled' ? <PlayCircle /> : <PauseCircle />}{item.status === 'disabled' ? 'Ativar' : 'Pausar'}</button>])} /><RegistryPanel page="integrations" subpage={subpage} records={records} tenants={data.tenants} onChange={load} /></>;
  }
  if (subpage === 'E-mail') {
    const messages = (data.outbound || []).filter((item: any) => item.channel === 'email');
    return <><Head eyebrow="INTEGRAÇÕES / COMUNICAÇÃO" title="Entrega de e-mails" text="Volume transacional, falhas, templates e remetentes homologados." icon={<Mail />} /><Metrics items={[["Mensagens", messages.length], ["Enviadas", messages.filter((x: any) => x.status === 'sent').length], ["Na fila", messages.filter((x: any) => x.status === 'queued').length], ["Falhas", messages.filter((x: any) => x.status === 'failed').length]]} /><Table heads={['Empresa / destinatário', 'Template', 'Agendamento', 'Situação', 'Diagnóstico']} rows={messages.slice(0, 100).map((item: any) => [<span><b>{item.companyName || 'Plataforma'}</b><small>{item.recipient}</small></span>, item.template, date(item.scheduledAt || item.createdAt), <Badge value={item.status} />, item.error || '—'])} /><RegistryPanel page="integrations" subpage={subpage} records={records} tenants={data.tenants} onChange={load} /></>;
  }
  const connectorTerms: Record<string, string[]> = { CRM: ['crm'], Pagamentos: ['asaas', 'stripe', 'payment', 'pagamento'], SSO: ['sso', 'saml', 'oidc'] }, terms = connectorTerms[subpage] || [], linked = (data.connectors || []).filter((item: any) => terms.some(term => JSON.stringify(item).toLowerCase().includes(term)));
  return <><Head eyebrow="INTEGRAÇÕES / PORTFÓLIO" title={subpage} text={registryDefinitions[`integrations:${subpage}`]?.text || 'Governança de integrações externas.'} icon={<Plug />} /><Metrics items={[["Configurações", records.length], ["Ativas", records.filter((x: any) => x.status === 'active').length], ["Conexões detectadas", linked.length], ["Críticas", records.filter((x: any) => x.priority === 'critical').length]]} />{linked.length > 0 && <Table heads={['Empresa', 'Provedor', 'Situação', 'Última atividade']} rows={linked.map((item: any) => [item.companyName, item.provider, <Badge value={item.status} />, date(item.lastSyncAt)])} />}<RegistryPanel page="integrations" subpage={subpage} records={records} tenants={data.tenants} onChange={load} /></>;
}

function OperationsWorkspace({ subpage, data, records, load, setNotice }: any) {
  const jobs = data.jobs || [], retry = async (job: any) => { await api(`/platform/jobs/${job.id}/retry`, { method: 'POST' }); setNotice('Processamento reenfileirado e registrado na auditoria.'); await load(); };
  if (subpage === 'Filas') {
    const groups = Object.values(jobs.reduce((acc: any, job: any) => { const key = job.type; acc[key] ||= { type: key, total: 0, queued: 0, processing: 0, completed: 0, failed: 0, attempts: 0 }; acc[key].total++; acc[key][job.status]++; acc[key].attempts += Number(job.attempts || 0); return acc; }, {}));
    return <><Head eyebrow="OPERAÇÕES / ORQUESTRAÇÃO" title="Filas de processamento" text="Backlog, vazão, falhas e tentativas por tipo de carga assíncrona." icon={<Workflow />} /><Metrics items={[["Mensagens", jobs.length], ["Aguardando", jobs.filter((x: any) => x.status === 'queued').length], ["Em execução", jobs.filter((x: any) => x.status === 'processing').length], ["Falhas", jobs.filter((x: any) => x.status === 'failed').length]]} /><Table heads={['Fila', 'Volume', 'Aguardando / executando', 'Concluídos', 'Falhas / tentativas']} rows={(groups as any[]).map(group => [humanJob(group.type), group.total, `${group.queued} / ${group.processing}`, group.completed, `${group.failed} / ${group.attempts}`])} /><RegistryPanel page="operations" subpage={subpage} records={records} tenants={data.tenants} onChange={load} /></>;
  }
  if (subpage === 'Importações') {
    const imports = jobs.filter((job: any) => job.type.startsWith('import_') || job.type.includes('sync'));
    return <><Head eyebrow="OPERAÇÕES / DADOS" title="Importações" text="Histórico de cargas, sincronizações, rejeições e reprocessamento por empresa." icon={<FileClock />} /><Metrics items={[["Execuções", imports.length], ["Concluídas", imports.filter((x: any) => x.status === 'completed').length], ["Falhas", imports.filter((x: any) => x.status === 'failed').length], ["Taxa de sucesso", percent(imports.filter((x: any) => x.status === 'completed').length, imports.length)]]} /><JobTable jobs={imports} retry={retry} /></>;
  }
  if (subpage === 'Exportações' || subpage === 'Agendamentos') return <><Head eyebrow="OPERAÇÕES / AUTOMAÇÃO" title={subpage} text={registryDefinitions[`operations:${subpage}`].text} icon={subpage === 'Exportações' ? <FileClock /> : <Clock3 />} /><Metrics items={[["Registros", records.length], ["Ativos", records.filter((x: any) => x.status === 'active').length], ["Pendentes", records.filter((x: any) => x.status === 'pending').length], ["Com atenção", records.filter((x: any) => ['critical', 'high'].includes(x.priority)).length]]} /><RegistryPanel page="operations" subpage={subpage} records={records} tenants={data.tenants} onChange={load} /></>;
  const title = subpage === 'Jobs' ? 'Jobs assíncronos' : 'Processamentos ponta a ponta';
  return <><Head eyebrow="OPERAÇÕES / EXECUÇÃO" title={title} text={subpage === 'Jobs' ? 'Controle técnico de tarefas, tentativas, duração e resultado.' : 'Rastreabilidade de processos por empresa, origem, etapa e conclusão.'} icon={<Workflow />} /><Metrics items={[["Execuções", jobs.length], ["Concluídas", jobs.filter((x: any) => x.status === 'completed').length], ["Em andamento", jobs.filter((x: any) => ['queued', 'processing'].includes(x.status)).length], ["Falhas", jobs.filter((x: any) => x.status === 'failed').length]]} /><JobTable jobs={jobs} retry={retry} /></>;
}
function JobTable({ jobs, retry }: { jobs: any[]; retry: (job: any) => void }) { return <Table heads={['Empresa / processo', 'Criado', 'Duração', 'Situação', 'Ação']} rows={jobs.map(job => [<span><b>{job.companyName}</b><small>{humanJob(job.type)} · {job.attempts} tentativa(s)</small></span>, date(job.createdAt), duration(job.startedAt, job.completedAt), <span><Badge value={job.status} />{job.error && <small className="danger-text">{job.error}</small>}</span>, job.status === 'failed' ? <button className="pa-inline-action" onClick={() => retry(job)}><RefreshCw /> Reprocessar</button> : '—'])} />; }

function MonitoringWorkspace({ subpage, data, records, load }: any) {
  const runtime = data.runtime || {}, jobs = data.jobs || [], connectors = data.connectors || [], database = data.database || {}, availability = runtime.requests ? Math.max(0, 100 - runtime.errors / runtime.requests * 100).toFixed(2) : '100.00';
  if (subpage === 'Status dos serviços') {
    const services = [['API Fidelizei', Number(availability) >= 99 ? 'Operacional' : 'Degradado', `${runtime.requests || 0} requisições observadas`], ['Banco de dados', database.integrity === 'ok' ? 'Operacional' : 'Atenção', `Integridade: ${database.integrity}`], ['Processador de filas', jobs.some((x: any) => x.status === 'failed') ? 'Atenção' : 'Operacional', `${jobs.filter((x: any) => ['queued', 'processing'].includes(x.status)).length} pendência(s)`], ['Integrações', connectors.some((x: any) => x.status === 'error' || x.lastError) ? 'Atenção' : 'Operacional', `${connectors.length} conexão(ões)`]];
    return <><Head eyebrow="MONITORAMENTO / DISPONIBILIDADE" title="Status dos serviços" text="Condição atual dos componentes críticos e dependências da plataforma." icon={<Server />} /><Metrics items={[["Disponibilidade", `${availability}%`], ["Serviços", services.length], ["Operacionais", services.filter(x => x[1] === 'Operacional').length], ["Incidentes abertos", (data.incidents || []).filter((x: any) => x.status !== 'resolved').length]]} /><div className="pa-service-grid">{services.map(([name, state, detail]) => <article className="pa-card" key={name}><i className={state === 'Operacional' ? 'healthy' : 'warning'}>{state === 'Operacional' ? <CheckCircle2 /> : <AlertTriangle />}</i><h3>{name}</h3><b>{state}</b><p>{detail}</p></article>)}</div></>;
  }
  if (subpage === 'Banco de dados') {
    const allocated = database.pageCount * database.pageSize, free = database.freePages * database.pageSize;
    return <><Head eyebrow="MONITORAMENTO / DADOS" title="Banco de dados" text="Capacidade, integridade, páginas livres e modo de persistência da instância." icon={<Database />} /><Metrics items={[["Integridade", database.integrity || '—'], ["Tamanho alocado", bytes(allocated)], ["Espaço reutilizável", bytes(free)], ["Tabelas", database.tables || 0]]} /><div className="pa-grid"><section className="pa-card"><h3>Armazenamento SQLite</h3><Detail label="Páginas alocadas" value={database.pageCount} /><Detail label="Tamanho da página" value={bytes(database.pageSize)} /><Detail label="Páginas livres" value={database.freePages} /><Detail label="Journal mode" value={database.journalMode} /></section><section className="pa-card pa-guidance"><h3>Recomendações operacionais</h3><p><CheckCircle2 /> Verificação rápida de integridade em tempo real.</p><p><CheckCircle2 /> Retenção e backups governados em Configurações.</p><p><AlertTriangle /> Acompanhe crescimento antes de ampliar capacidade.</p></section></div></>;
  }
  if (subpage === 'Performance') {
    const statusEntries = Object.entries(runtime.byStatus || {});
    return <><Head eyebrow="MONITORAMENTO / APM" title="Performance" text="Latência, volume, erros e distribuição das respostas da API." icon={<Activity />} /><Metrics items={[["Resposta média", `${Math.round(runtime.averageResponseMs || 0)} ms`], ["Requisições", runtime.requests || 0], ["Erros 5xx", runtime.errors || 0], ["Uptime", uptime(runtime.uptimeSeconds || 0)]]} /><section className="pa-card"><h3>Distribuição HTTP</h3><div className="pa-horizontal-bars">{statusEntries.length ? statusEntries.map(([code, count]) => <div key={code}><span>HTTP {code}</span><i style={{ width: `${Math.max(4, Number(count) / Math.max(1, runtime.requests) * 100)}%` }} /><b>{String(count)}</b></div>) : <Empty>As métricas aparecerão após o tráfego da API.</Empty>}</div></section></>;
  }
  if (subpage === 'Logs') {
    const logs = [...(data.auditLogs || []).map((x: any) => ({ ...x, source: 'Auditoria', detail: `${x.action} · ${x.entityType}` })), ...(data.outbound || []).filter((x: any) => x.error).map((x: any) => ({ ...x, source: 'Comunicação', detail: x.error }))].sort((a: any, b: any) => String(b.createdAt).localeCompare(String(a.createdAt)));
    return <><Head eyebrow="MONITORAMENTO / INVESTIGAÇÃO" title="Logs centralizados" text="Eventos administrativos e falhas operacionais reunidos para investigação." icon={<Search />} /><Metrics items={[["Eventos", logs.length], ["Auditoria", logs.filter((x: any) => x.source === 'Auditoria').length], ["Erros de comunicação", logs.filter((x: any) => x.source === 'Comunicação').length], ["Últimas 24h", logs.filter((x: any) => recent(x.createdAt, 24)).length]]} /><Table heads={['Origem', 'Evento', 'Responsável / empresa', 'IP', 'Data']} rows={logs.slice(0, 200).map((log: any) => [log.source, log.detail, log.actor || log.companyName || 'Sistema', log.ip || '—', date(log.createdAt)])} /><RegistryPanel page="monitoring" subpage={subpage} records={records} tenants={data.tenants} onChange={load} /></>;
  }
  const statusEntries = Object.entries(runtime.byStatus || {});
  return <><Head eyebrow="MONITORAMENTO / COMMAND CENTER" title={subpage === 'APIs' ? 'Observabilidade das APIs' : 'Dashboard técnico'} text="Visão consolidada de tráfego, capacidade, filas, integrações e riscos operacionais." icon={<Activity />} /><Metrics items={[["Disponibilidade", `${availability}%`], ["Latência média", `${Math.round(runtime.averageResponseMs || 0)} ms`], ["Backlog", jobs.filter((x: any) => ['queued', 'processing'].includes(x.status)).length], ["Integrações com erro", connectors.filter((x: any) => x.status === 'error' || x.lastError).length]]} /><div className="pa-grid"><section className="pa-card"><h3>Respostas da API</h3>{statusEntries.length ? statusEntries.map(([code, count]) => <Detail key={code} label={`HTTP ${code}`} value={String(count)} />) : <Empty>Sem tráfego nesta instância desde a inicialização.</Empty>}</section><section className="pa-card"><h3>Riscos prioritários</h3><Detail label="Jobs com falha" value={jobs.filter((x: any) => x.status === 'failed').length} /><Detail label="Conectores com erro" value={connectors.filter((x: any) => x.status === 'error' || x.lastError).length} /><Detail label="Incidentes não resolvidos" value={(data.incidents || []).filter((x: any) => x.status !== 'resolved').length} /><Detail label="Erros de entrega" value={(data.outbound || []).filter((x: any) => x.status === 'failed').length} /></section></div>{subpage === 'APIs' && <RegistryPanel page="monitoring" subpage={subpage} records={records} tenants={data.tenants} onChange={load} />}</>;
}

function SecurityWorkspace({ subpage, data, records, load, setNotice }: any) {
  if (subpage === 'Central SOC') {
    const events=data.securityEvents||[],summary=data.securitySummary||{},open=events.filter((x:any)=>['open','investigating'].includes(x.status));
    const treat=async(id:string,status:string)=>{const note=prompt('Registre uma observação para a tratativa (opcional):')??'';await api(`/platform/security/events/${id}`,{method:'PATCH',body:JSON.stringify({status,note})});setNotice(status==='investigating'?'Evento assumido para investigação.':'Evento contido e registrado na auditoria.');await load();};
    return <><Head eyebrow="SEGURANÇA / COMMAND CENTER" title="Central SOC" text="Detecção correlacionada, priorização e contenção dos eventos de segurança da plataforma." icon={<ShieldCheck/>}/><Metrics items={[["Eventos abertos",Number(summary.openEvents||open.length)],["Críticos",Number(summary.criticalEvents||0)],["Ataques a credenciais (24h)",Number(summary.credentialAttacks24h||0)],["IPs suspeitos (24h)",Number(summary.suspiciousIps24h||0)]]}/>{!Number(data.identities?.platformMfaEnabled||0)&&<div className="pa-notice security-warning"><AlertTriangle/> A conta administrativa ainda não usa MFA. Ative-a no submenu MFA antes de ampliar a operação.</div>}<Table heads={['Risco / identidade','Origem','Ocorrências','Última detecção','Tratativa']} rows={events.map((event:any)=>[<span><Badge value={event.severity}/><b>{securityEventName(event.eventType)}</b><small>{event.identity||userType(event.userType)} · {event.reason}</small></span>,<span><b>{event.ip||'Origem não informada'}</b><small>{compactAgent(event.userAgent)}</small></span>,event.occurrenceCount||1,date(event.lastSeenAt),<span className="pa-actions">{event.status==='open'&&<button className="pa-inline-action" onClick={()=>void treat(event.id,'investigating')}><Search/>Investigar</button>}{['open','investigating'].includes(event.status)&&<button className="pa-inline-action danger" onClick={()=>void treat(event.id,'contained')}><ShieldCheck/>Conter</button>}{!['open','investigating'].includes(event.status)&&<Badge value={event.status}/>}</span>])}/></>;
  }
  if (subpage === 'Sessões ativas') {
    const sessions = data.sessions || [];
    return <><Head eyebrow="SEGURANÇA / IDENTIDADE" title="Sessões ativas" text="Acessos atuais de administradores, lojistas e clientes com revogação imediata." icon={<LockKeyhole />} /><Metrics items={[["Sessões", sessions.length], ["Administradores", sessions.filter((x: any) => x.userType === 'platform').length], ["Lojistas", sessions.filter((x: any) => x.userType === 'company').length], ["Clientes", sessions.filter((x: any) => x.userType === 'customer').length]]} /><Table heads={['Identidade', 'Origem / IP', 'Última atividade', 'Expiração', 'Ação']} rows={sessions.map((session: any) => [<span><b>{session.name}</b><small>{session.email} · {userType(session.userType)}</small></span>, <span><b>{session.companyName}</b><small>{session.ipAddress||'IP não registrado'} · {compactAgent(session.userAgent)}</small></span>, date(session.lastSeenAt||session.createdAt), date(session.expiresAt), <button className="pa-inline-action danger" onClick={async () => { await api(`/platform/sessions/${session.id}`, { method: 'DELETE' }); setNotice('Sessão revogada e evento auditado.'); await load(); }}><X /> Revogar</button>])} /></>;
  }
  if (subpage === 'Log de acessos') {
    const logs = data.accessLogs || [], denied = logs.filter((x: any) => !x.success).length;
    return <><Head eyebrow="SEGURANÇA / AUTENTICAÇÃO" title="Log de acessos" text="Autenticações dos três perfis, origem, navegador e motivo de bloqueio." icon={<ShieldCheck />} /><Metrics items={[["Tentativas", logs.length], ["Permitidas", logs.length - denied], ["Negadas", denied], ["IPs distintos", new Set(logs.map((x: any) => x.ip).filter(Boolean)).size]]} /><Table heads={['Perfil / empresa', 'Resultado', 'IP', 'Dispositivo', 'Data']} rows={logs.map((log: any) => [<span><b>{userType(log.userType)}</b><small>{log.companyName || 'Fidelizei'}</small></span>, <span><Badge value={log.success ? 'active' : 'error'} />{log.reason && <small>{log.reason}</small>}</span>, log.ip || '—', compactAgent(log.userAgent), date(log.createdAt)])} /></>;
  }
  if (subpage === 'Auditoria' || subpage === 'Log de alterações') {
    const all = data.auditLogs || [], items = subpage === 'Log de alterações' ? all.filter((x: any) => /update|create|delete|status|revoke|retry|adjustment|changed/.test(x.action)) : all;
    return <><Head eyebrow="SEGURANÇA / GOVERNANÇA" title={subpage} text={subpage === 'Auditoria' ? 'Trilha imutável das decisões administrativas e entidades afetadas.' : 'Mudanças críticas, responsável, IP e momento exato da alteração.'} icon={<FileClock />} /><Metrics items={[["Eventos", items.length], ["Responsáveis", new Set(items.map((x: any) => x.actor).filter(Boolean)).size], ["Entidades", new Set(items.map((x: any) => x.entityType)).size], ["Últimas 24h", items.filter((x: any) => recent(x.createdAt, 24)).length]]} /><Table heads={['Responsável', 'Ação', 'Entidade / ID', 'IP', 'Data']} rows={items.map((item: any) => [item.actor || 'Sistema', item.action, <span><b>{item.entityType}</b><small>{item.entityId || '—'}</small></span>, item.ip || '—', date(item.createdAt)])} /><PolicyForm subpage={subpage} settings={data.settings} onSaved={load} /></>;
  }
  if (subpage === 'LGPD') return <><Head eyebrow="SEGURANÇA / PRIVACIDADE" title="Gestão LGPD" text="Solicitações de titulares, base legal, evidências, responsáveis e prazos." icon={<ShieldCheck />} /><Metrics items={[["Processos", records.length], ["Pendentes", records.filter((x: any) => x.status === 'pending').length], ["Críticos", records.filter((x: any) => x.priority === 'critical').length], ["Vencidos", records.filter((x: any) => x.dueAt && new Date(x.dueAt) < new Date() && x.status !== 'resolved').length]]} /><RegistryPanel page="security" subpage={subpage} records={records} tenants={data.tenants} onChange={load} /><PolicyForm subpage={subpage} settings={data.settings} onSaved={load} /></>;
  if (subpage === 'MFA') {
    const identities = data.identities || {};
    return <><Head eyebrow="SEGURANÇA / IDENTIDADE" title="Autenticação multifator" text="Cobertura de MFA, obrigatoriedade por perfil e proteção da conta administrativa." icon={<KeyRound />} /><Metrics items={[["Admins protegidos", `${identities.platformMfaEnabled||0}/${identities.platformAdmins||0}`], ["Usuários corporativos", identities.companyUsers || 0], ["MFA configurado", identities.mfaEnabled || 0], ["Cobertura lojistas", percent(identities.mfaEnabled || 0, identities.companyUsers || 0)]]} /><PlatformMfaControl enabled={Boolean(identities.platformMfaEnabled)} onSaved={load}/><PolicyForm subpage={subpage} settings={data.settings} onSaved={load} /></>;
  }
  if (subpage === 'Controle de permissões') {
    const permissions = data.permissions || [];
    return <><Head eyebrow="SEGURANÇA / AUTORIZAÇÃO" title="Controle de permissões" text="Matriz de menor privilégio, segregação de funções e mudanças auditadas." icon={<LockKeyhole />} /><Metrics items={[["Permissões", permissions.length], ["Ativas", permissions.filter((x: any) => x.enabled).length], ["Perfis", new Set(permissions.map((x: any) => x.role)).size], ["Bloqueadas", permissions.filter((x: any) => !x.enabled).length]]} /><div className="pa-permission-matrix">{permissions.map((permission: any) => <label key={`${permission.role}-${permission.permission}`}><span><b>{permission.role} · {permission.permission}</b><small>{permission.description}</small></span><input type="checkbox" defaultChecked={!!permission.enabled} onChange={async event => { await api(`/platform/permissions/${permission.role}/${permission.permission}`, { method: 'PATCH', body: JSON.stringify({ enabled: event.target.checked }) }); setNotice('Permissão atualizada e auditada.'); await load(); }} /></label>)}</div></>;
  }
  return <><Head eyebrow="SEGURANÇA / CREDENCIAIS" title="Política de senhas" text="Complexidade, tentativas, bloqueio e ciclo seguro das credenciais." icon={<KeyRound />} /><Metrics items={[["Tamanho mínimo", data.settings?.['security.password_min'] || 10], ["Tentativas", data.settings?.['security.lock_attempts'] || 5], ["Sessões ativas", (data.sessions || []).length], ["Acessos negados", (data.accessLogs || []).filter((x: any) => !x.success).length]]} /><PolicyForm subpage={subpage} settings={data.settings} onSaved={load} /></>;
}

export function PlatformMfaControl({enabled,onSaved}:{enabled:boolean;onSaved:()=>Promise<void>}){
  const[setup,setSetup]=useState<{secret:string;uri:string}|null>(null),[message,setMessage]=useState('');
  async function begin(){try{setSetup(await api('/platform/me/security/2fa/setup',{method:'POST',body:JSON.stringify({})})as {secret:string;uri:string});setMessage('Chave criada. Conclua a confirmação para ativar.')}catch(reason){setMessage((reason as Error).message)}}
  async function confirmMfa(event:FormEvent<HTMLFormElement>){event.preventDefault();const code=String(new FormData(event.currentTarget).get('code')||'');try{await api('/platform/me/security/2fa/confirm',{method:'POST',body:JSON.stringify({code})});setMessage('MFA ativado com sucesso. Guarde o acesso ao autenticador.');setSetup(null);await onSaved()}catch(reason){setMessage((reason as Error).message)}}
  async function disableMfa(event:FormEvent<HTMLFormElement>){event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget))as Record<string,string>;try{await api('/platform/me/security/2fa',{method:'DELETE',body:JSON.stringify({password:values.password,code:values.code})});setMessage('MFA desativado e demais sessões revogadas.');await onSaved()}catch(reason){setMessage((reason as Error).message)}}
  if(enabled)return <section className="pa-card pa-mfa-control"><header><div><h3>Conta administrativa protegida</h3><p>O segundo fator está ativo. Um código temporário será exigido em todos os novos acessos.</p></div><CheckCircle2/></header><form onSubmit={disableMfa}><label>Para desativar, confirme sua senha<input name="password" type="password" minLength={10} maxLength={128} autoComplete="current-password" required/></label><label>Código atual<input name="code" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} required/></label><button className="danger">Desativar MFA</button>{message&&<small>{message}</small>}</form></section>;
  return <section className="pa-card pa-mfa-control"><header><div><h3>Proteja a conta principal</h3><p>Use Google Authenticator, Microsoft Authenticator, 1Password ou outro aplicativo TOTP.</p></div><AlertTriangle/></header>{!setup?<button onClick={()=>void begin()}><KeyRound/>Configurar MFA agora</button>:<form onSubmit={confirmMfa}><label>Chave para adicionar manualmente<input readOnly value={setup.secret}/></label><small className="pa-mfa-uri">Conta: {setup.uri}</small><label>Código de 6 dígitos<input name="code" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6} placeholder="000000" required/></label><button>Confirmar e ativar MFA</button></form>}{message&&<small className="success-text">{message}</small>}</section>;
}

const policyDefinitions: Record<string, [string, string, string][]> = {
  Auditoria: [['audit.retention_days', 'Retenção dos logs (dias)', '365'], ['audit.export_enabled', 'Exportação permitida', 'true']],
  'Log de alterações': [['audit.changes_enabled', 'Registrar alterações administrativas', 'true'], ['audit.changes_alert_critical', 'Alertar mudança crítica', 'true']],
  LGPD: [['lgpd.dpo_email', 'E-mail do encarregado', ''], ['lgpd.request_days', 'Prazo de atendimento (dias)', '15'], ['lgpd.retention_months', 'Retenção operacional (meses)', '60']],
  MFA: [['security.mfa_admin', 'Obrigatório para administradores', 'true'], ['security.mfa_company', 'Obrigatório para lojistas', 'false'], ['security.mfa_grace_days', 'Prazo de adesão (dias)', '7']],
  'Política de senhas': [['security.password_min', 'Tamanho mínimo', '10'], ['security.lock_attempts', 'Tentativas antes do bloqueio', '5'], ['security.session_hours', 'Sessão do lojista (horas)', '24'], ['security.admin_session_hours', 'Sessão administrativa (horas)', '12'], ['security.customer_session_hours', 'Sessão do cliente (horas)', '168']]
};
function PolicyForm({ subpage, settings = {}, onSaved }: { subpage: string; settings: Record<string, string>; onSaved: () => Promise<void> }) {
  const [notice, setNotice] = useState(''), fields = policyDefinitions[subpage] || policyDefinitions.Auditoria;
  return <form className="pa-card pa-policy-form" onSubmit={async event => { event.preventDefault(); await api('/platform/settings', { method: 'PATCH', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); setNotice('Política salva e registrada na auditoria.'); await onSaved(); }}><header><div><h3>Política aplicável</h3><p>Configuração persistente da plataforma.</p></div><ShieldCheck /></header>{fields.map(([key, label, fallback]) => <label key={key}>{label}<input name={key} defaultValue={settings[key] ?? fallback} /></label>)}<button>Salvar política</button>{notice && <small className="success-text">{notice}</small>}</form>;
}
function SupportWorkspace({ subpage, data, setNotice }: any) {
  const definitions: Record<string, [string, string, string][]> = { SLA: [['support.sla_low_hours', 'Baixa prioridade (h)', '72'], ['support.sla_medium_hours', 'Média prioridade (h)', '24'], ['support.sla_high_hours', 'Alta prioridade (h)', '8'], ['support.sla_critical_hours', 'Crítica (h)', '2']], Feedbacks: [['support.feedback_enabled', 'Coleta de feedback', 'true'], ['support.feedback_min_score', 'Nota mínima saudável', '4']], 'Base de conhecimento': [['support.knowledge_public', 'Base pública', 'true'], ['support.knowledge_review_days', 'Revisão dos artigos (dias)', '90']], Notificações: [['support.notify_assignee', 'Notificar responsável', 'true'], ['support.escalation_email', 'E-mail de escalonamento', '']] };
  const fields = definitions[subpage] || definitions.SLA;
  return <><Head eyebrow="SUPORTE / GOVERNANÇA" title={subpage} text="Configuração persistente das políticas, comunicação e qualidade do atendimento." icon={<Workflow />} /><form className="pa-card pa-policy-form" onSubmit={async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); await api('/platform/settings', { method: 'PATCH', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); setNotice('Política de suporte salva e auditada.'); }}><header><div><h3>Parâmetros operacionais</h3><p>Aplicação global para a central de suporte.</p></div><ShieldCheck /></header>{fields.map(([key, label, fallback]) => <label key={key}>{label}<input name={key} defaultValue={data.settings?.[key] ?? fallback} /></label>)}<button>Salvar configuração</button></form></>;
}

function RegistryPanel({ page, subpage, records, tenants, onChange }: { page: string; subpage: string; records: ModuleRecord[]; tenants: any[]; onChange: () => Promise<void> }) {
  const definition = registryDefinitions[`${page}:${subpage}`];
  const [selected, setSelected] = useState<ModuleRecord | null>(null);
  const [query, setQuery] = useState('');
  const [status, setStatus] = useState('all');
  const [priority, setPriority] = useState('all');
  const [order, setOrder] = useState('updated');
  const [view, setView] = useState<'table' | 'grid'>('table');
  const [checked, setChecked] = useState<string[]>([]);
  const statuses = [...new Set(records.map(record => record.status).filter(Boolean))];
  const priorities = [...new Set(records.map(record => record.priority).filter(Boolean))];
  const visible = records.filter(record => {
    const searchable = [record.title, record.companyName, record.owner, record.status, record.priority].join(' ').toLocaleLowerCase('pt-BR');
    return searchable.includes(query.trim().toLocaleLowerCase('pt-BR')) && (status === 'all' || record.status === status) && (priority === 'all' || record.priority === priority);
  }).sort((left, right) => order === 'title' ? left.title.localeCompare(right.title, 'pt-BR') : order === 'company' ? (left.companyName || '').localeCompare(right.companyName || '', 'pt-BR') : (right.updatedAt || '').localeCompare(left.updatedAt || ''));
  const exported = checked.length ? visible.filter(record => checked.includes(record.id)) : visible;
  const exportCsv = () => downloadCsv(`registros-${page}-${slug(subpage)}.csv`, ['Título', 'Empresa', 'Status', 'Prioridade', 'Responsável', 'Prazo', 'Atualizado em'], exported.map(record => [record.title, record.companyName || 'Plataforma', labels[record.status] || record.status, labels[record.priority] || record.priority, record.owner || '', record.dueAt ? date(record.dueAt) : '', record.updatedAt ? date(record.updatedAt) : '']));
  if (!definition) return null;
  return <section className="pa-card pa-registry">
    <header><div><h3>{definition.title}</h3><p>{definition.text}</p></div><button type="button" onClick={() => setSelected({ id: '', title: '', status: 'active', priority: 'medium', payload: {} })}><Plus /> {definition.action}</button></header>
    <div className="pa-registry-tools">
      <label className="pa-registry-search"><Search size={17} /><input aria-label="Pesquisar registros" placeholder="Pesquisar título, empresa ou responsável" value={query} onChange={event => setQuery(event.target.value)} /></label>
      <select aria-label="Filtrar status" value={status} onChange={event => setStatus(event.target.value)}><option value="all">Todos os status</option>{statuses.map(item => <option key={item} value={item}>{labels[item] || item}</option>)}</select>
      <select aria-label="Filtrar prioridade" value={priority} onChange={event => setPriority(event.target.value)}><option value="all">Todas as prioridades</option>{priorities.map(item => <option key={item} value={item}>{labels[item] || item}</option>)}</select>
      <select aria-label="Ordenar registros" value={order} onChange={event => setOrder(event.target.value)}><option value="updated">Mais recentes</option><option value="title">Título A–Z</option><option value="company">Empresa A–Z</option></select>
      <div className="pa-registry-views"><button type="button" aria-label="Visualizar tabela" aria-pressed={view === 'table'} onClick={() => setView('table')}><List size={17} /></button><button type="button" aria-label="Visualizar grade" aria-pressed={view === 'grid'} onClick={() => setView('grid')}><LayoutGrid size={17} /></button></div>
      <button type="button" className="pa-registry-export" disabled={!exported.length} onClick={exportCsv}><Download size={16} /> Exportar {checked.length ? `(${exported.length})` : ''}</button>
    </div>
    <p className="pa-registry-count">{visible.length} de {records.length} registros · {checked.length ? `${checked.length} selecionados` : 'Selecione para exportar somente os itens desejados'}</p>
    {visible.length ? <div className={`pa-registry-results pa-registry-${view}`}>
      {view === 'table' && <div className="pa-registry-row pa-registry-head"><input type="checkbox" aria-label="Selecionar registros visíveis" checked={visible.every(record => checked.includes(record.id))} onChange={event => setChecked(event.target.checked ? [...new Set([...checked, ...visible.map(record => record.id)])] : checked.filter(id => !visible.some(record => record.id === id)))} /><span>Registro</span><span>Empresa</span><span>Status</span><span>Responsável</span><span>Prazo</span></div>}
      {visible.map(record => <div className="pa-registry-row" key={record.id}><input type="checkbox" aria-label={`Selecionar ${record.title}`} checked={checked.includes(record.id)} onChange={event => setChecked(event.target.checked ? [...checked, record.id] : checked.filter(id => id !== record.id))} /><button type="button" onClick={() => setSelected({ ...record, payload: parsePayload(record.payload) })}><b>{record.title}</b></button><span>{record.companyName || 'Plataforma'}</span><span><Badge value={record.status} /></span><span>{record.owner || '—'}</span><span>{record.dueAt ? date(record.dueAt) : '—'}</span></div>)}
    </div> : <Empty>{records.length ? 'Nenhum registro corresponde aos filtros.' : `Nenhum registro cadastrado. Use “${definition.action}” para iniciar a gestão.`}</Empty>}
    {selected && <RecordModal page={page} subpage={subpage} item={selected} definition={definition} tenants={tenants} onClose={() => setSelected(null)} onSaved={async () => { setSelected(null); setChecked([]); await onChange(); }} />}
  </section>;
}
function RecordModal({ page, subpage, item, definition, tenants, onClose, onSaved }: any) {
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>, body = { title: values.title, tenantId: values.tenantId || null, status: values.status, priority: values.priority, owner: values.owner, dueAt: values.dueAt || null, payload: { first: values.first, second: values.second, notes: values.notes } }; await api(`/platform/modules/${page}/${slug(subpage)}${item.id ? `/${item.id}` : ''}`, { method: item.id ? 'PATCH' : 'POST', body: JSON.stringify(body) }); await onSaved(); }
  async function remove() { if (!item.id || !confirm('Excluir este registro gerencial? A exclusão ficará registrada no histórico.')) return; await api(`/platform/modules/${page}/${slug(subpage)}/${item.id}`, { method: 'DELETE' }); await onSaved(); }
  return <><button className="pa-detail-backdrop" onClick={onClose} aria-label="Fechar" /><aside className="pa-detail pa-system-drawer"><header><div><small>{item.id ? 'EDITAR REGISTRO' : 'NOVO REGISTRO'}</small><h2>{definition.action}</h2></div><button onClick={onClose} aria-label="Fechar" title="Fechar"><X /></button></header><form className="pa-record-form" onSubmit={submit}><label>Título<input name="title" required minLength={2} defaultValue={item.title} /></label><label>Empresa<select name="tenantId" defaultValue={item.tenantId || ''}><option value="">Plataforma / global</option>{tenants.map((tenant: any) => <option key={tenant.id} value={tenant.id}>{tenant.name}</option>)}</select></label><div className="pa-form-grid"><label>Status<select name="status" defaultValue={item.status || 'active'}><option value="draft">Rascunho</option><option value="active">Ativo</option><option value="pending">Pendente</option><option value="paused">Pausado</option><option value="resolved">Resolvido</option><option value="archived">Arquivado</option><option value="error">Com erro</option></select></label><label>Prioridade<select name="priority" defaultValue={item.priority || 'medium'}><option value="low">Baixa</option><option value="medium">Média</option><option value="high">Alta</option><option value="critical">Crítica</option></select></label></div><label>Responsável<input name="owner" defaultValue={item.owner || ''} /></label><label>Prazo<input type="datetime-local" name="dueAt" defaultValue={toLocalInput(item.dueAt)} /></label><label>{definition.first}<input name="first" defaultValue={String(item.payload?.first || '')} /></label><label>{definition.second}<input name="second" defaultValue={String(item.payload?.second || '')} /></label><label>Notas operacionais<textarea name="notes" defaultValue={String(item.payload?.notes || '')} /></label><button>Salvar registro</button>{item.id && <button type="button" className="danger" onClick={remove}><Trash2 /> Excluir registro</button>}</form></aside></>;
}
function Table({ heads, rows }: { heads: string[]; rows: ReactNode[][] }) { return <div className="pa-table pa-system-table"><div className="pa-system-tr pa-th">{heads.map(head => <span key={head}>{head}</span>)}</div>{rows.length ? rows.map((row, index) => <div className="pa-system-tr" key={index}>{row.map((cell, cellIndex) => <span key={cellIndex}>{cell}</span>)}</div>) : <Empty />}</div>; }
function Detail({ label, value }: { label: string; value: ReactNode }) { return <div className="pa-row"><span>{label}</span><b>{value}</b></div>; }
function safeList(value: unknown) { try { const parsed = typeof value === 'string' ? JSON.parse(value) : value; return Array.isArray(parsed) ? parsed.join(' · ') : String(value || '—'); } catch { return String(value || '—'); } }
function parsePayload(value: unknown): Record<string, unknown> { if (!value) return {}; if (typeof value !== 'string') return value as Record<string, unknown>; try { return JSON.parse(value) as Record<string, unknown>; } catch { return {}; } }
function humanJob(value: string) { return ({ import_customers: 'Importação de clientes', import_sales: 'Importação de vendas', refresh_gie: 'Atualização do GIE', sync_bling: 'Sincronização Bling' } as Record<string, string>)[value] || value.replace(/_/g, ' '); }
function duration(start?: string, end?: string) { if (!start) return '—'; const finish = end ? new Date(end).getTime() : Date.now(), seconds = Math.max(0, Math.round((finish - new Date(start).getTime()) / 1000)); return seconds < 60 ? `${seconds}s` : `${Math.floor(seconds / 60)}m ${seconds % 60}s`; }
function percent(value: number, total: number) { return total ? `${Math.round(value / total * 100)}%` : '0%'; }
function bytes(value: number) { if (!Number.isFinite(value) || value <= 0) return '0 B'; const units = ['B', 'KB', 'MB', 'GB'], exponent = Math.min(Math.floor(Math.log(value) / Math.log(1024)), units.length - 1); return `${(value / 1024 ** exponent).toFixed(exponent ? 1 : 0)} ${units[exponent]}`; }
function uptime(seconds: number) { const days = Math.floor(seconds / 86400), hours = Math.floor(seconds % 86400 / 3600), minutes = Math.floor(seconds % 3600 / 60); return days ? `${days}d ${hours}h` : `${hours}h ${minutes}m`; }
function recent(value: string, hours: number) { return Boolean(value && Date.now() - new Date(value).getTime() <= hours * 3600000); }
function userType(value: string) { return ({ platform: 'Administrador', company: 'Lojista', customer: 'Cliente' } as Record<string, string>)[value] || value; }
function compactAgent(value?: string) { if (!value) return '—'; if (/Mobile|Android|iPhone/i.test(value)) return 'Dispositivo móvel'; if (/Chrome/i.test(value)) return 'Chrome'; if (/Firefox/i.test(value)) return 'Firefox'; if (/Safari/i.test(value)) return 'Safari'; return value.slice(0, 45); }
function securityEventName(value:string){return({brute_force:'Força bruta',credential_stuffing:'Credential stuffing',cross_site_request:'Requisição entre sites bloqueada',unsafe_method:'Método HTTP bloqueado',oversized_credential:'Credencial fora do limite'}as Record<string,string>)[value]||value.replace(/_/g,' ')}
function toLocalInput(value?: string) { if (!value) return ''; const dateValue = new Date(value); return Number.isNaN(dateValue.getTime()) ? '' : new Date(dateValue.getTime() - dateValue.getTimezoneOffset() * 60000).toISOString().slice(0, 16); }
